def calc_valuation(fields):
    """信号1: 估值严重度（全A PE绝对值 + 半导体PE分位）— 核心信号"""
    results = []

    # 全A: PE绝对值为主 <50/50-60/≥60
    pe = fields.get('全A_PE(倍)')
    pe_pct = fields.get('全A_PE分位(%)')
    if pe is not None:
        if pe >= 60:
            sev, reason = '严重', f'PE={pe:.1f}倍 ≥ 60倍'
        elif pe >= 50:
            sev, reason = '警告', f'PE={pe:.1f}倍（50-60倍区间）'
        else:
            sev, reason = '安全', f'PE={pe:.1f}倍 < 50倍'
    else:
        sev, reason = '安全', '数据缺失'
    results.append({
        'group': '估值', 'name': '全A估值', 'value': pe, 'severity': sev,
        'reason': reason, 'is_core': True,
        'threshold_display': 'PE<50/50-60/≥60倍', 'is_pct': False,
    })

    # 半导体: PE分位 + PB分位 取更高严重度 <90/90-95/≥95%（军师：PB分位99%亦极贵）
    spe_pct = fields.get('半导体_PE分位(%)')
    spb_pct = fields.get('半导体_PB分位(%)')
    spe = fields.get('半导体_PE(倍)')
    spb = fields.get('半导体_PB(倍)')

    def _sev(pct, label, abs_val):
        if pct is None:
            return '安全', f'{label}分位缺失'
        disp = f'{pct*100:.1f}%'
        suffix = f'（{label}={abs_val:.1f}倍）' if abs_val is not None else ''
        if pct >= 0.95:
            return '严重', f'{label}分位={disp} ≥ 95%{suffix}'
        if pct >= 0.90:
            return '警告', f'{label}分位={disp}（90-95%）{suffix}'
        return '安全', f'{label}分位={disp} < 90%{suffix}'

    rank = {'安全': 0, '警告': 1, '严重': 2}
    sev_pe, re_pe = _sev(spe_pct, 'PE', spe)
    sev_pb, re_pb = _sev(spb_pct, 'PB', spb)
    if spe_pct is None and spb_pct is None:
        sev, reason = '安全', '数据缺失'
    elif rank[sev_pb] > rank[sev_pe]:
        sev, reason = sev_pb, re_pb
    else:
        sev, reason = sev_pe, re_pe

    results.append({
        'group': '估值', 'name': '半导体估值', 'value': spe_pct, 'severity': sev,
        'reason': reason, 'is_core': True,
        'threshold_display': 'PE/PB分位<90%/90-95%/≥95%', 'is_pct': True,
    })

    return results


