    print('\n📊 IPO首发历史回补（纯首发口径，仅更新IPO字段，不动其他字段）...')
    month_data = {}
    end_date = datetime.now().strftime('%Y-%m-%d')

    status, data = call_wind('analytics_data', 'get_financial_data', {
        'question': 'A股2022年11月至今每月IPO首发募集资金总额',
    })
    if status == 'BALANCE_INSUFFICIENT':
        bs[0] = True
        return 0
    if status != 'ok' or not data:
        print('⚠️ IPO历史查询失败')
        return 0
    try:
        step = data['data']['data'][0]
        cols = [c['name'] for c in step['columns']]
        ipo_col = next((c for c in cols if '首发' in c and '增发' not in c and '再融资' not in c), None)
        date_col = next((c for c in cols if '日期' in c or '截止' in c or '月份' in c), None)
        if date_col and ipo_col:
            for row in step['rows']:
                rd = dict(zip(cols, row))
                dte = str(rd.get(date_col, ''))
                if not dte:
                    continue
                ym = dte[:7].replace('-', '')[:6]
                v = _safe_float(rd.get(ipo_col))
                if v and v > 0:
                    month_data[ym] = round(v, 1)
    except (KeyError, IndexError, TypeError) as e:
        print(f'  ⚠️ IPO历史解析失败: {e}')
        return 0

    if not month_data:
        print('⚠️ 未获取到IPO历史数据')
        return 0
    print(f'  查询到 {len(month_data)} 个月（{min(month_data)}~{max(month_data)}）')

    if dry_run:
        for ym in sorted(month_data.keys())[-5:]:
            print(f'  [DRY-RUN] {ym}: IPO首发={month_data[ym]}亿')
        print(f'  ...（共{len(month_data)}个月）')
        return 0

    # 一次全表 fetch 建立 ym → record_id 映射（避免逐月全表查询）
    ids, records, fidx = fetch_records_with_fields(BASE_TOKEN, SIGNAL_TREND_TABLE)
    ym_to_rid = {}
    for rid, rec in zip(ids, records):
        date_val = str(get_field(rec, fidx, '日期'))
        if len(date_val) >= 7:
            ym_to_rid[date_val[:7].replace('-', '')] = rid

    success = 0
    for ym in sorted(month_data.keys()):
        rid = ym_to_rid.get(ym)
        if not rid:
            print(f'  ⚠️ 趋势表无 {ym} 记录，跳过')
            continue
        payload = json.dumps({'IPO首发(亿元)': month_data[ym]}, ensure_ascii=False)
        result = subprocess.run(
            [LARK_CLI, 'base', '+record-upsert',
             '--base-token', BASE_TOKEN,
             '--table-id', SIGNAL_TREND_TABLE,
             '--record-id', rid,
             '--json', payload],
            capture_output=True, text=True)
        if result.returncode == 0:
            try:
                resp = json.loads(result.stdout)
                if resp.get('ok'):
                    success += 1
                    continue
            except (ValueError, TypeError):
                pass
        print(f'  ❌ 更新 {ym} 失败: {result.stdout[:120]}')
        time.sleep(0.3)

    print(f'✅ IPO首发历史回补完成 {success}/{len(month_data)}个月')
    return success


