def backfill_trend_extra(bs, dry_run=False):
    """回补趋势表辅助历史：两融余额/两融占市值 + 美股近1年涨幅

    - 两融×2：analytics_data 月度序列（"过去5年每月末A股的融资融券余额" / "过去5年每月A股融资融券余额占流通市值比例"）
    - 美股近1年涨幅：index_data 月K线（SOX.GI/IXIC.GI 自2021-11），滚动12月收盘价涨幅
    - 只更新对应字段，不动其他字段。减持/估值分位历史无法低成本获取（Wind无序列），跳过
    积分：analytics×2 + kline×2 ≈ 2.7分
    """
    print('\n📊 辅助历史回补（两融余额/占市值 + 美股近1年涨幅，仅更新对应字段）...')
    month_data = {}
    end_date = datetime.now().strftime('%Y-%m-%d')

    # 1. 两融余额（万亿 → 亿元）
    status, data = call_wind('analytics_data', 'get_financial_data', {
        'question': '过去5年每月末A股的融资融券余额',
    })
    if status == 'BALANCE_INSUFFICIENT':
        bs[0] = True
        return 0
    if status == 'ok' and data:
        try:
            step = data['data']['data'][0]
            cols = [c['name'] for c in step['columns']]
            date_col = next((c for c in cols if c == '日期'), None)
            bal_col = next((c for c in cols if '融资融券余额' in c and '合计' in c), None)
            if date_col and bal_col:
                for row in step['rows']:
                    rd = dict(zip(cols, row))
                    dte = str(rd.get(date_col, ''))
                    v = _safe_float(rd.get(bal_col))
                    if dte and v is not None and v > 0:
                        ym = dte[:7].replace('-', '')
                        # 万亿 → 亿元
                        month_data.setdefault(ym, {})['两融余额(亿元)'] = round(v * 10000, 1)
                print(f'  两融余额: {sum(1 for m in month_data if "两融余额(亿元)" in month_data[m])}个月')
        except (KeyError, IndexError, TypeError) as e:
            print(f'  ⚠️ 两融余额序列解析失败: {e}')
    else:
        print('  ⚠️ 两融余额序列查询失败')

    # 2. 两融占流通市值比例（小数比值）
    if not bs[0]:
        time.sleep(0.3)
        status, data = call_wind('analytics_data', 'get_financial_data', {
            'question': '过去5年每月A股融资融券余额占流通市值比例',
        })
        if status == 'BALANCE_INSUFFICIENT':
            bs[0] = True
        elif status == 'ok' and data:
            try:
                step = data['data']['data'][0]
                cols = [c['name'] for c in step['columns']]
                year_col = next((c for c in cols if c == '年份'), None)
                month_col = next((c for c in cols if c == '月份'), None)
                ratio_col = next((c for c in cols if '融资融券余额占流通市值比例' in c), None)
                if year_col and month_col and ratio_col:
                    for row in step['rows']:
                        rd = dict(zip(cols, row))
                        y, m = rd.get(year_col), rd.get(month_col)
                        v = _safe_float(rd.get(ratio_col))
                        if y is None or m is None or v is None or v <= 0:
                            continue
                        ym = f'{int(float(y)):04d}{int(float(m)):02d}'
                        month_data.setdefault(ym, {})['两融占流通市值(%)'] = round(v, 6)
                    print(f'  两融占市值: {sum(1 for m in month_data if "两融占流通市值(%)" in month_data[m])}个月')
            except (KeyError, IndexError, TypeError) as e:
                print(f'  ⚠️ 两融占市值序列解析失败: {e}')

    # 3. 美股近1年涨幅（月K线滚动12月）
    for code, prefix in [('SOX.GI', '费城半导体'), ('IXIC.GI', '纳斯达克')]:
        if bs[0]:
            break
        time.sleep(0.3)
        status, data = call_wind('index_data', 'get_index_kline', {
            'windcode': code,
            'begin_date': '2021-11-01',
            'end_date': end_date,
            'period': '1mo',
        })
        if status == 'BALANCE_INSUFFICIENT':
            bs[0] = True
            break
        if status != 'ok' or not data:
            print(f'  ⚠️ {prefix}月K线查询失败')
            continue
        try:
            rows = data['data']['rows']
            # 按时间升序，取 (ym, 收盘价)
            seq = []
            for row in rows:
                time_str = str(row[0]) if row[0] else ''
                close = _safe_float(row[2] if len(row) > 2 else None)  # MATCH 收盘
                if time_str and close and close > 0:
                    ym = time_str[:7].replace('-', '')
                    seq.append((ym, close))
            seq.sort()
            for i in range(12, len(seq)):
                ym, close = seq[i]
                prev_close = seq[i - 12][1]
                gain = round(close / prev_close - 1, 6)
                month_data.setdefault(ym, {})[f'{prefix}近1年涨幅(%)'] = gain
            print(f'  {prefix}近1年涨幅: {sum(1 for m in month_data if f"{prefix}近1年涨幅(%)" in month_data[m])}个月（K线{len(seq)}个月）')
        except (KeyError, IndexError, TypeError) as e:
            print(f'  ⚠️ {prefix}涨幅计算失败: {e}')

    if not month_data:
        print('⚠️ 未获取到回补数据')
        return 0

    if dry_run:
        for ym in sorted(month_data.keys())[-6:]:
            print(f'  [DRY-RUN] {ym}: {json.dumps(month_data[ym], ensure_ascii=False)}')
        print(f'  ...（共{len(month_data)}个月）')
        return 0

    # 逐月 upsert（一次全表 fetch 建立映射）
    ids, records, fidx = fetch_records_with_fields(BASE_TOKEN, SIGNAL_TREND_TABLE)
    ym_to_rid = {}
    for rid, rec in zip(ids, records):
        date_val = str(get_field(rec, fidx, '日期'))
        if len(date_val) >= 7:
            ym_to_rid[date_val[:7].replace('-', '')] = rid

    success = 0
    total_fields = 0
    for ym in sorted(month_data.keys()):
        rid = ym_to_rid.get(ym)
        if not rid:
            print(f'  ⚠️ 趋势表无 {ym} 记录，跳过')
            continue
        payload = json.dumps(month_data[ym], ensure_ascii=False)
