def query_us_stocks(bs):
    """信号8: 美股走势 — 费城半导体 + 纳斯达克 近1年涨幅（涨幅轨）

    回撤轨暂用近3月涨幅推算（若近3月涨幅为负，视为回撤信号）。
    """
    print("📊 [信号8] 查询美股走势（费城半导体 + 纳斯达克）...")
    fields = {}
    for idx_name, wind_name, prefix in [
        ('费城半导体', '费城半导体指数', '费城半导体'),
        ('纳斯达克', '纳斯达克综合指数', '纳斯达克'),
    ]:
        if bs[0]:
            break
        status, data = call_wind('analytics_data', 'get_financial_data', {
            'question': f'{wind_name}近一年涨幅和近三月涨幅',
        })
        if status == 'BALANCE_INSUFFICIENT':
            bs[0] = True
            break
        if status != 'ok' or not data:
            time.sleep(0.3)
            continue
        try:
            for step in data['data']['data']:
                cols = [c['name'] for c in step['columns']]
                if not step['rows']:
                    continue
                rd = dict(zip(cols, step['rows'][0]))
                for key, val in rd.items():
                    v = _safe_float(val)
                    if v is None:
                        continue
                    if '涨' not in key:
                        continue
                    pct = _pct_raw_to_decimal(v)
                    if pct is None:
                        continue
                    # 归一化中文数字：一→1, 三→3
                    kn = key.replace('一', '1').replace('三', '3')
                    if '1年' in kn:
                        fields[f'{prefix}近1年涨幅(%)'] = pct
                    elif '3月' in kn:
                        fields[f'{prefix}近3月涨幅(%)'] = pct
        except (KeyError, IndexError, TypeError) as e:
            print(f"  ⚠️ {idx_name}解析失败: {e}")
        time.sleep(0.3)

    sox = fields.get('费城半导体近1年涨幅(%)')
    nas = fields.get('纳斯达克近1年涨幅(%)')
    print(f"  费城半导体近1年={sox} 近3月={fields.get('费城半导体近3月涨幅(%)')}")
    print(f"  纳斯达克近1年={nas} 近3月={fields.get('纳斯达克近3月涨幅(%)')}")
    return fields


